 removeDotSegments(path) {
  let input = String(path)
  let output = ''

  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = output.replace(/\/?[^/]*$/, '')
    } else if (input === '/..') {
      input = '/'
      output = output.replace(/\/?[^/]*$/, '')
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const slash = input.indexOf('/', input.startsWith('/') ? 1 : 0)
      if (slash < 0) {
        output += input
        input = ''
      } else {
